{"witnessCode": "import { it } from 'node:test';
import { strictEqual } from 'node:assert/strict';
import x from '../index.js';

it('stripWWW should strip www for two-letter TLD .co', () => {
  const url = 'http://www.example.co/';
  const opts = { stripWWW: true };
  const expected = 'http://example.co';
  const actual = x(url, opts);
  strictEqual(actual, expected);
});"}
